package com.uthmani.quran.data

/**
 * Arabic text normalization for SEARCH ONLY.
 *
 * The stored Quran text is NEVER modified; this normalizer is applied to
 * (a) user queries at runtime and (b) the precomputed `text_simple` column
 * generated by scripts/build_db.py — both sides MUST use identical rules.
 */
object QuranTextNormalizer {

    /** Codepoint ranges removed before comparison. */
    private val REMOVE_RANGES: List<IntRange> = listOf(
        0x0610..0x061A, // Arabic honorific signs
        0x0640..0x0640, // tatweel
        0x064B..0x065F, // tashkeel (harakat)
        0x0670..0x0670, // superscript alef
        0x06D6..0x06ED, // Quranic annotation marks (pause marks, small waw, ...)
        0x08D3..0x08FF, // extended Arabic marks
    )

    /** Single-char unifications. */
    private val REPLACEMENTS: Map<Char, Char> = mapOf(
        '\u0622' to '\u0627', // آ -> ا
        '\u0623' to '\u0627', // أ -> ا
        '\u0625' to '\u0627', // إ -> ا
        '\u0671' to '\u0627', // ٱ (alef wasla) -> ا
        '\u0629' to '\u0647', // ة -> ه
        '\u0649' to '\u064A', // ى -> ي
        '\u06CC' to '\u064A', // ی -> ي
        '\u06A9' to '\u0643', // ک -> ك
        '\u0626' to '\u064A', // ئ -> ي
        '\u0624' to '\u0648', // ؤ -> و
    )

    fun normalize(text: String): String {
        if (text.isEmpty()) return text
        val sb = StringBuilder(text.length)
        for (ch in text) {
            val code = ch.code
            if (REMOVE_RANGES.any { code in it }) continue
            sb.append(REPLACEMENTS[ch] ?: ch)
        }
        return sb.toString()
    }

    /**
     * Normalize while keeping a map from each output index to its original index,
     * used to highlight matches inside the original (fully-vocalized) text.
     */
    fun normalizeWithMap(text: String): Pair<String, List<Int>> {
        val sb = StringBuilder(text.length)
        val map = ArrayList<Int>(text.length)
        for ((i, ch) in text.withIndex()) {
            val code = ch.code
            if (REMOVE_RANGES.any { code in it }) continue
            sb.append(REPLACEMENTS[ch] ?: ch)
            map.add(i)
        }
        return sb.toString() to map
    }

    /**
     * All occurrences of [query] inside [original], ignoring diacritics.
     * Ranges refer to indices of the ORIGINAL string.
     */
    fun matchRanges(original: String, query: String): List<IntRange> {
        val q = normalize(query)
        if (q.isBlank()) return emptyList()
        val (norm, map) = normalizeWithMap(original)
        val ranges = mutableListOf<IntRange>()
        var from = 0
        while (true) {
            val idx = norm.indexOf(q, from)
            if (idx < 0) break
            val start = map[idx]
            val end = map[idx + q.length - 1]
            ranges.add(start..end)
            from = idx + q.length
        }
        return ranges
    }
}
